/** 初始状态。 */
export const INITIAL = { enhancing: false, hasEnhanced: false, lastDraft: '' };
const states = new Map();
const listeners = new Map();
/** 读取会话状态。 */
export function getState(sessionId) {
    return sessionId === undefined ? INITIAL : states.get(sessionId) ?? INITIAL;
}
/** 订阅会话状态变化。 */
export function subscribe(sessionId, listener) {
    let set = listeners.get(sessionId);
    if (set === undefined) {
        set = new Set();
        listeners.set(sessionId, set);
    }
    set.add(listener);
    return () => { set.delete(listener); };
}
/** 局部更新（引用不变时跳过通知）。 */
export function patch(sessionId, partial) {
    const current = states.get(sessionId) ?? INITIAL;
    const next = { ...current, ...partial };
    const keys = Object.keys(next);
    if (keys.every(k => current[k] === next[k]))
        return;
    states.set(sessionId, next);
    listeners.get(sessionId)?.forEach(l => l(next));
}
/** 清空会话状态（会话销毁 / 草稿清空时）。 */
export function clearSession(sessionId) {
    states.delete(sessionId);
    listeners.get(sessionId)?.forEach(l => l(INITIAL));
}
/**
 * 声明"我方即将写入这个草稿值"（值比对抑制，幂等）。
 * 在下一次草稿变化通知到达时，若值相等则视为我方写入、跳过分歧判定。
 *
 * @param sessionId - 会话标识。
 * @param draft - 即将写入的草稿值。
 */
export function suppressNextDraft(sessionId, draft) {
    patch(sessionId, { expectedDraft: draft });
}
/**
 * 草稿变化通知（含值比对抑制）。
 *
 * @returns 本次变化是否被抑制（我方写入）。
 */
export function notifyDraftChanged(sessionId, draft) {
    const state = getState(sessionId);
    // 我方写入：值命中期望 → 消费期望并跳过。
    if (state.expectedDraft !== undefined && state.expectedDraft === draft) {
        patch(sessionId, { expectedDraft: undefined, lastDraft: draft });
        return true;
    }
    onContentDiverged(sessionId, draft);
    return false;
}
/**
 * 分歧判定核心。
 *
 * 草稿变化时调用：
 *   - 草稿 === 增强结果  → 确保 hasEnhanced = true（用户改回原样）
 *   - 草稿 !== 增强结果  → 清空 hasEnhanced + backup（用户改动过，增强态失效）
 *
 * @param sessionId - 会话标识。
 * @param draft - 当前草稿（含空白）。
 */
export function onContentDiverged(sessionId, draft) {
    const state = getState(sessionId);
    // 记录已知草稿（抑制护栏用）。
    if (state.lastDraft !== draft)
        patch(sessionId, { lastDraft: draft });
    // 无备份（从未增强 / 已清）直接返回，不做任何事。
    if (state.backup === undefined)
        return;
    const normalized = draft.replace(/\u200B/g, '').trim();
    const isStillEnhanced = normalized === state.backup.after.trim();
    if (isStillEnhanced) {
        if (!state.hasEnhanced)
            patch(sessionId, { hasEnhanced: true });
        return;
    }
    // 分歧：增强结果已被改动/删除 → 恢复成初始（只保留 suppress）。
    patch(sessionId, {
        hasEnhanced: false,
        backup: undefined,
        errorMessage: undefined,
    });
}
/** 竞速：signal abort 立即拒绝，不等网络。 */
export class EnhanceAbortedError extends Error {
    constructor() {
        super('prompt-better-aborted-by-user');
        this.name = 'AbortError';
    }
}
/** 竞速：外部取消立即拒绝。 */
export function raceWithAbortSignal(promise, signal) {
    if (signal === undefined)
        return promise;
    if (signal.aborted)
        return Promise.reject(new EnhanceAbortedError());
    return new Promise((resolve, reject) => {
        const onAbort = () => { cleanup(); reject(new EnhanceAbortedError()); };
        const cleanup = () => { signal.removeEventListener('abort', onAbort); };
        signal.addEventListener('abort', onAbort, { once: true });
        promise.then(value => { cleanup(); resolve(value); }, error => { cleanup(); reject(error); });
    });
}
